<?php foreach ($rows as $a): ?><div class="panel" style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><b><?= e($a['label']) ?></b> <?= $a['is_default'] ? '<span class="badge b-ok">Par défaut</span>' : '' ?><br><?= e($a['name']) ?> · <?= e($a['phone']) ?><br><?= e($a['address']) ?>, <?= e($a['commune']) ?> <?= e($a['city']) ?></div><form method="post" action="/compte/adresses/<?= (int) $a['id'] ?>/supprimer" data-confirm="Supprimer cette adresse ?"><?= csrf_field() ?><button class="btn btn-d btn-sm">Supprimer</button></form></div><?php endforeach; ?>
